def answer(question):
    words = question.split()
    if words[0] != "What" or words[1] != "is" or not question.endswith("?"):
        raise ValueError("unknown operation")

    tokens = words[2:-1]

    operations = {
        "plus": lambda a, b: a + b,
        "minus": lambda a, b: a - b,
        "multiplied": None,
        "divided": None,
        "by": None,
    }

    ops = {
        "plus": lambda a, b: a + b,
        "minus": lambda a, b: a - b,
        "multiplied by": lambda a, b: a * b,
        "divided by": lambda a, b: a / b,
    }

    def parse_number(token):
        try:
            return int(token)
        except ValueError:
            raise ValueError("syntax error")

    def is_number(token):
        try:
            int(token)
            return True
        except ValueError:
            return False

    def is_operation(tokens, i):
        return any(tokens[i:i + len(op)] == op.split() for op in ops)

    i = 0
    if not tokens or not is_number(tokens[0]):
        raise ValueError("syntax error")

    result = int(tokens[0])
    i = 1
    expect_number = False
    while i < len(tokens):
        # find matching operation starting at i
        matched = None
        for op, func in ops.items():
            parts = op.split()
            if tokens[i:i + len(parts)] == parts:
                matched = (op, func, len(parts))
                break
        if matched is None:
            raise ValueError("unknown operation")
        op, func, oplen = matched
        i += oplen
        if i >= len(tokens) or not is_number(tokens[i]):
            raise ValueError("syntax error")
        operand = int(tokens[i])
        i += 1
        if op == "divided by" and operand == 0:
            pass  # let ZeroDivisionError or result happen naturally
        result = func(result, operand)

    if isinstance(result, float) and result.is_integer():
        result = int(result)
    return result
