            if is_number(tokens[i]):
                raise ValueError("syntax error")
            raise ValueError("unknown operation")
        op, func, oplen = matched
        i += oplen
        if i >= len(tokens) or not is_number(tokens[i]):
            raise ValueError("syntax error")
        operand = int(tokens[i])
